{"formatVersion":3,"title":"Coffee Cup Counter","description":"Count today's cups and hear a short beep with each cup.","capabilities":["audio.tone"],"capabilityResults":false,"stateSchema":{"count":"number","dayKey":"string"},"initialState":{"count":0,"dayKey":""},"ui":{"type":"column","children":[{"type":"metric","text":"Cups today","bind":"count","style":{"emphasis":"number"}},{"type":"text","text":"Each Add cup logs a cup and plays a short beep.","style":{"tone":"muted"}},{"type":"button","text":"Add cup","action":"addCup","variant":"filled"},{"type":"button","text":"Reset","action":"resetCount","variant":"text"}]},"source":"const s = input.state;
const e = input.event;

function todayKey() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

if (e.type === 'action') {
  if (e.actionId === 'addCup') {
    const today = todayKey();
    const base = s.dayKey === today ? s.count : 0;
    const count = base + 1;
    return {
      state: { count: count, dayKey: today },
      effects: [
        { id: 'beep', capability: 'audio.tone', args: { tone: 'beep', durationMillis: 120 } }
      ]
    };
  }
  if (e.actionId === 'resetCount') {
    return { state: { count: 0, dayKey: s.dayKey } };
  }
}

return { state: s };"}
